<?php
declare(strict_types=1);
require_once __DIR__.'/stock.php';
const SUPERVISOR_XLSX_NS='http://schemas.openxmlformats.org/spreadsheetml/2006/main';
function supervisor_xml(string $xml):DOMDocument {if(strlen($xml)>12000000||stripos($xml,'<!DOCTYPE')!==false||stripos($xml,'<!ENTITY')!==false)throw new CatalogException('El Excel contiene una hoja no compatible.',422);$doc=new DOMDocument();$before=libxml_use_internal_errors(true);$ok=$doc->loadXML($xml,LIBXML_NONET);libxml_clear_errors();libxml_use_internal_errors($before);if(!$ok)throw new CatalogException('No pudimos leer el Excel.',422);return $doc;}
function supervisor_archive(string $bytes,callable $work):mixed {
 if(strlen($bytes)>3000000||!str_starts_with($bytes,"PK\x03\x04"))throw new CatalogException('Elegí un archivo .xlsx de hasta 3 MB.',422);$tmp=tempnam(sys_get_temp_dir(),'rt-xlsx-');unlink($tmp);$path=$tmp.'.zip';file_put_contents($path,$bytes);chmod($path,0600);
 try{$zip=new PharData($path);$size=0;$count=0;foreach(new RecursiveIteratorIterator($zip) as $entry){$size+=$entry->getSize();if(++$count>1500||$size>25000000||$entry->isLink())throw new CatalogException('El Excel es demasiado grande.',422);}return $work($zip);}catch(CatalogException $e){throw $e;}catch(Throwable $e){throw new CatalogException('El archivo no es un Excel .xlsx válido.',422);}finally{unset($zip);if(is_file($path))unlink($path);}
}
function supervisor_column(int $n):string {$out='';while($n>0){$n--;$out=chr(65+$n%26).$out;$n=intdiv($n,26);}return $out;}
function supervisor_column_number(string $column):int {$n=0;foreach(str_split($column)as$c)$n=$n*26+ord($c)-64;return $n;}
function supervisor_sheet(PharData $zip):string {
 if(!isset($zip['xl/workbook.xml'],$zip['xl/_rels/workbook.xml.rels']))throw new CatalogException('El Excel no tiene hojas disponibles.',422);$doc=supervisor_xml($zip['xl/workbook.xml']->getContent());$sheet=$doc->getElementsByTagNameNS(SUPERVISOR_XLSX_NS,'sheet')->item(0);if(!$sheet)throw new CatalogException('El Excel no tiene hojas.',422);$id=$sheet->getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id');$rels=supervisor_xml($zip['xl/_rels/workbook.xml.rels']->getContent());foreach($rels->getElementsByTagName('Relationship')as$rel)if($rel->getAttribute('Id')===$id&&$rel->getAttribute('TargetMode')!=='External'){$path=$rel->getAttribute('Target');$path=str_starts_with($path,'/')?ltrim($path,'/'):'xl/'.$path;if(!preg_match('~^xl/worksheets/[A-Za-z0-9_-]+\.xml$~D',$path)||!isset($zip[$path]))break;return $path;}throw new CatalogException('La primera hoja del Excel no es compatible.',422);
}
function supervisor_cells(PharData $zip,string $path):array {
 $shared=[];if(isset($zip['xl/sharedStrings.xml']))foreach(supervisor_xml($zip['xl/sharedStrings.xml']->getContent())->getElementsByTagNameNS(SUPERVISOR_XLSX_NS,'si')as$si){$text='';foreach($si->getElementsByTagNameNS(SUPERVISOR_XLSX_NS,'t')as$t)$text.=$t->textContent;$shared[]=$text;if(count($shared)>50000)throw new CatalogException('El Excel tiene demasiadas celdas.',422);}
 $sheet=supervisor_xml($zip[$path]->getContent());$rows=[];$max=0;$count=0;foreach($sheet->getElementsByTagNameNS(SUPERVISOR_XLSX_NS,'row')as$row){$r=(int)$row->getAttribute('r');if($r<1||$r>10001)throw new CatalogException('La lista admite hasta 10.000 filas de productos.',422);foreach($row->getElementsByTagNameNS(SUPERVISOR_XLSX_NS,'c')as$cell){if(++$count>100000)throw new CatalogException('El Excel tiene demasiadas celdas.',422);if(!preg_match('/^([A-Z]{1,3})[0-9]+$/D',$cell->getAttribute('r'),$m))throw new CatalogException('El Excel tiene referencias de celda no válidas.',422);$col=$m[1];$number=supervisor_column_number($col);if($number>200)throw new CatalogException('La lista admite hasta 200 columnas.',422);$max=max($max,$number);$value=$cell->getElementsByTagNameNS(SUPERVISOR_XLSX_NS,'v')->item(0)?->textContent??'';if($cell->getAttribute('t')==='s')$value=$shared[(int)$value]??'';elseif($cell->getAttribute('t')==='inlineStr'){$value='';foreach($cell->getElementsByTagNameNS(SUPERVISOR_XLSX_NS,'t')as$t)$value.=$t->textContent;}$rows[$r][$col]=['value'=>$value,'formula'=>$cell->getElementsByTagNameNS(SUPERVISOR_XLSX_NS,'f')->length>0];}}
 return [$sheet,$rows,$max];
}
function supervisor_parse_xlsx(string $bytes,string $column=''):array {
 return supervisor_archive($bytes,function($zip)use($column){$path=supervisor_sheet($zip);[, $rows,$max]=supervisor_cells($zip,$path);if(!isset($rows[1]))throw new CatalogException('La primera fila debe contener los títulos de las columnas.',422);$columns=[];$suggested='';for($i=1;$i<=$max;$i++){$c=supervisor_column($i);$label=trim($rows[1][$c]['value']??'');$columns[]=['value'=>$c,'label'=>$c.' · '.($label?:'Sin título')];if(preg_match('/ean|c[oó]digo.*barras|gtin/iu',$label))$suggested=$c;}
 if($column==='')return ['columns'=>$columns,'suggested'=>$suggested?:'A','sheet_path'=>$path];if(!preg_match('/^[A-Z]{1,2}$/D',$column)||supervisor_column_number($column)>$max)throw new CatalogException('Elegí la columna de EAN.',422);$eanRows=[];$invalid=[];foreach($rows as$r=>$cells){if($r===1)continue;$cell=$cells[$column]??['value'=>'','formula'=>false];$ean=trim($cell['value']);if($ean==='')continue;if(is_numeric($ean)&&preg_match('/[Ee.]/',$ean)&&is_finite((float)$ean)&&(float)$ean===floor((float)$ean))$ean=sprintf('%.0f',(float)$ean);if($cell['formula']||!valid_product_ean($ean)){$invalid[]=$r;continue;}$eanRows[(string)$r]=$ean;}
 if($invalid)throw new CatalogException('Revisá los EAN de las filas '.implode(', ',array_slice($invalid,0,8)).(count($invalid)>8?'…':'').'. Deben estar completos y sin fórmulas.',422);if(!$eanRows)throw new CatalogException('No encontramos EAN en esa columna.',422);return ['sheet_path'=>$path,'ean_column'=>$column,'ean_rows'=>$eanRows,'row_count'=>count($eanRows)];});
}
function supervisor_number_cell(DOMDocument $doc,string $reference,int $value):DOMElement {$c=$doc->createElementNS(SUPERVISOR_XLSX_NS,'c');$c->setAttribute('r',$reference);$c->setAttribute('t','n');$c->appendChild($doc->createElementNS(SUPERVISOR_XLSX_NS,'v',(string)$value));return $c;}
function supervisor_compare_xlsx(string $bytes,string $path,array $eanRows,array $totals):string {
 return supervisor_archive($bytes,function($zip)use($path,$eanRows,$totals){if(!preg_match('~^xl/worksheets/[A-Za-z0-9_-]+\.xml$~D',$path)||!isset($zip[$path]))throw new CatalogException('La hoja ya no está disponible.',422);[$doc,$originalRows,$max]=supervisor_cells($zip,$path);$col=supervisor_column($max+1);foreach($doc->getElementsByTagNameNS(SUPERVISOR_XLSX_NS,'row')as$row){$r=(int)$row->getAttribute('r');if($r===1){$c=$doc->createElementNS(SUPERVISOR_XLSX_NS,'c');$c->setAttribute('r',$col.'1');$c->setAttribute('t','inlineStr');$headers=$row->getElementsByTagNameNS(SUPERVISOR_XLSX_NS,'c');$previous=$headers->item($headers->length-1);if($previous?->hasAttribute('s'))$c->setAttribute('s',$previous->getAttribute('s'));$is=$doc->createElementNS(SUPERVISOR_XLSX_NS,'is');$t=$doc->createElementNS(SUPERVISOR_XLSX_NS,'t');$t->textContent='Stock (unidades)';$is->appendChild($t);$c->appendChild($is);$row->appendChild($c);}elseif(isset($eanRows[$r]))$row->appendChild(supervisor_number_cell($doc,$col.$r,(int)($totals[$eanRows[$r]]??0)));}
 $dimension=$doc->getElementsByTagNameNS(SUPERVISOR_XLSX_NS,'dimension')->item(0);if($dimension)$dimension->setAttribute('ref','A1:'.$col.(max(array_map('intval',array_keys($originalRows)))?:1));$zip[$path]=$doc->saveXML();return file_get_contents($zip->getPath());});
}
function supervisor_write_xlsx(array $rows):string {
 $tmp=tempnam(sys_get_temp_dir(),'rt-export-');unlink($tmp);$path=$tmp.'.zip';try{$zip=new PharData($path);$zip['[Content_Types].xml']='<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>';
 $zip['_rels/.rels']='<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>';
 $zip['xl/workbook.xml']='<?xml version="1.0"?><workbook xmlns="'.SUPERVISOR_XLSX_NS.'" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Stock" sheetId="1" r:id="rId1"/></sheets></workbook>';
 $zip['xl/_rels/workbook.xml.rels']='<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>';
 $doc=new DOMDocument('1.0','UTF-8');$sheet=$doc->createElementNS(SUPERVISOR_XLSX_NS,'worksheet');$doc->appendChild($sheet);$data=$doc->createElementNS(SUPERVISOR_XLSX_NS,'sheetData');$sheet->appendChild($data);foreach($rows as$i=>$values){$row=$doc->createElementNS(SUPERVISOR_XLSX_NS,'row');$row->setAttribute('r',(string)($i+1));foreach(array_values($values)as$j=>$value){$ref=supervisor_column($j+1).($i+1);if(is_int($value))$cell=supervisor_number_cell($doc,$ref,$value);else{$cell=$doc->createElementNS(SUPERVISOR_XLSX_NS,'c');$cell->setAttribute('r',$ref);$cell->setAttribute('t','inlineStr');$is=$doc->createElementNS(SUPERVISOR_XLSX_NS,'is');$t=$doc->createElementNS(SUPERVISOR_XLSX_NS,'t');$t->textContent=(string)$value;$is->appendChild($t);$cell->appendChild($is);}$row->appendChild($cell);}$data->appendChild($row);}$zip['xl/worksheets/sheet1.xml']=$doc->saveXML();return file_get_contents($path);}finally{unset($zip);if(is_file($path))unlink($path);}}
